import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

matmul_transposed_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void matmul_transposed_kernel(const float* A, const float* B, float* C,
                                         int K, int M, int N)
{
    // A shape: (K, M)
    // B shape: (N, K)
    // C shape: (M, N) = A.T @ B.T
    int row = blockIdx.x * blockDim.x + threadIdx.x;
    int col = blockIdx.y * blockDim.y + threadIdx.y;
    if (row < M && col < N) {
        float val = 0;
        for (int p = 0; p < K; p++) {
            val += A[p * M + row] * B[col * K + p];
        }
        C[row * N + col] = val;
    }
}

torch::Tensor matmul_transposed_cuda(torch::Tensor A, torch::Tensor B) {
    // A shape: (K, M)
    // B shape: (N, K)
    // we compute A.T @ B.T => (M, N)
    int K_ = A.size(0);
    int M_ = A.size(1);
    int N_ = B.size(0);

    auto options = A.options();
    auto C = torch::empty({M_, N_}, options);

    dim3 block(16, 16);
    dim3 grid((M_ + block.x - 1) / block.x, (N_ + block.y - 1) / block.y);
    matmul_transposed_kernel<<<grid, block>>>(A.data_ptr<float>(), B.data_ptr<float>(),
                                             C.data_ptr<float>(), K_, M_, N_);
    return C;
}
"""

matmul_transposed_cpp_source = (
    "torch::Tensor matmul_transposed_cuda(torch::Tensor A, torch::Tensor B);"
)

transposed_matmul = load_inline(
    name="transposed_matmul",
    cpp_sources=matmul_transposed_cpp_source,
    cuda_sources=matmul_transposed_source,
    functions=["matmul_transposed_cuda"],
    verbose=False,
    extra_cflags=[],
    extra_ldflags=[],
)

class ModelNew(nn.Module):
    """
    Optimized model that performs a single matrix multiplication (C = A.T * B.T) with a custom CUDA kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return transposed_matmul.matmul_transposed_cuda(A, B)

M = 1024
K = 4096
N = 2048

def get_inputs():
    A = torch.randn(K, M)
    B = torch.randn(N, K)
    return [A, B]

